SPARQL:
SELECT ?item ?itemLabel ?elev WHERE {
  ?item wdt:P31/wdt:P279* wd:Q8502;
        wdt:P2044 ?elev;
        wdt:P17/wdt:P30 wd:Q49.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?elev)
OFFSET 6
LIMIT 1

SELECT (YEAR(?date) AS ?year) WHERE {
  ?series rdfs:label "A Song of Ice and Fire"@en.
  ?book wdt:P179 ?series;
        wdt:P577 ?date.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ASC(?date)
LIMIT 1

SELECT ?gov ?govLabel ?state ?stateLabel ?dob WHERE {
  ?state wdt:P31 wd:Q35657;
         wdt:P6 ?gov.
  ?gov wdt:P31 wd:Q5;
       wdt:P569 ?dob.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?dob)
LIMIT 1

ASK WHERE {
  wd:Q359442 wdt:P39 wd:Q11696.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?singer ?singerLabel ?age WHERE {
  VALUES ?class { wd:Q7366 wd:Q134556 }
  ?song wdt:P31 ?class;
        rdfs:label "The Dance"@en;
        wdt:P175 ?singer.
  ?singer wdt:P31 wd:Q5;
          wdt:P569 ?birth.
  BIND(NOW() AS ?now)
  BIND((YEAR(?now) - YEAR(?birth) - IF(MONTH(?now) < MONTH(?birth) || (MONTH(?now) = MONTH(?birth) && DAY(?now) < DAY(?birth)), 1, 0)) AS ?age)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?lake ?lakeLabel ?length WHERE {
  ?lake wdt:P31/wdt:P279* wd:Q23397.
  ?lake wdt:P2043 ?length.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?length)
LIMIT 1

SELECT ?place ?placeLabel WHERE {
  ?song wdt:P31 wd:Q7366;
        rdfs:label "Genie in a Bottle"@en;
        wdt:P175 ?singer.
  ?singer wdt:P31 wd:Q5;
          wdt:P19 ?place.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?game ?gameLabel WHERE {
  ?game wdt:P31 wd:Q7889;
        rdfs:label ?label.
  FILTER(LANG(?label) = "en").
  FILTER(CONTAINS(LCASE(?label), "super mario land")).
  FILTER(NOT EXISTS { ?game wdt:P674 wd:Q1406 }).
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (COUNT(DISTINCT ?series) AS ?losses) WHERE {
  ?ws rdfs:label "World Series"@en.
  ?franchise (wdt:P1365|wdt:P1366)* wd:Q45169.
  { ?series wdt:P361 ?ws } UNION { ?series wdt:P31 ?ws }.
  ?series (wdt:P710|^wdt:P1344) ?franchise.
  ?series wdt:P1346 ?winner.
  FILTER(?winner != ?franchise)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P19 wd:Q5092;
        wdt:P21 wd:Q6581097;
        wdt:P1344 wd:Q8567;
        wdt:P641 wd:Q31920.
  { ?item wdt:P1532 wd:Q30. } UNION { ?item wdt:P27 wd:Q30. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person p:P39 ?posStmt.
  ?posStmt ps:P39 ?position.
  ?position wdt:P1001 wd:Q1397.
  ?position rdfs:label ?posLabel.
  FILTER(LANG(?posLabel)="en").
  FILTER(LCASE(STR(?posLabel)) = "governor of ohio").
  OPTIONAL { ?posStmt pq:P580 ?start. }
  OPTIONAL { ?posStmt pq:P582 ?end. }
  BIND(COALESCE(?end, "9999-12-31T00:00:00Z"^^xsd:dateTime) AS ?e)
  FILTER(?e >= "2000-01-01T00:00:00Z"^^xsd:dateTime)
  FILTER(NOT EXISTS { ?posStmt pq:P102 wd:Q29468 } && NOT EXISTS { ?person wdt:P102 wd:Q29468 })
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

ASK WHERE {
  ?venus wdt:P31 wd:Q5; rdfs:label "Venus Williams"@en; wdt:P569 ?venusDOB.
  ?serena wdt:P31 wd:Q5; rdfs:label "Serena Williams"@en; wdt:P569 ?serenaDOB.
  FILTER(?venusDOB < ?serenaDOB)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

ASK {
  ?beatles rdfs:label "The Beatles"@en.
  ?rubberSoul rdfs:label "Rubber Soul"@en;
               wdt:P31 wd:Q482994;
               wdt:P175 ?beatles;
               wdt:P577 ?rsDate.
  ?revolver rdfs:label "Revolver"@en;
            wdt:P31 wd:Q482994;
            wdt:P175 ?beatles;
            wdt:P577 ?revDate.
  FILTER(?rsDate < ?revDate)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (COUNT(?awardStatement) AS ?count) WHERE {
  ?person rdfs:label "Colson Whitehead"@en;
          wdt:P31 wd:Q5;
          p:P166 ?awardStatement.
  ?awardStatement ps:P166 ?award.
  ?award wdt:P361 wd:Q35637.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?film ?filmLabel ?boxOffice WHERE {
  VALUES ?title { "Joker"@en "Suicide Squad"@en }
  ?film wdt:P31 wd:Q11424;
        rdfs:label ?title;
        wdt:P577 ?pubdate;
        wdt:P2142 ?boxOffice.
  FILTER(YEAR(?pubdate) IN (2019, 2016))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?boxOffice)
LIMIT 1

SELECT ?fridayYear ?halloweenYear (?fridayYear = ?halloweenYear AS ?sameYear) WHERE {
  {
    SELECT (MIN(YEAR(?date1)) AS ?fridayYear) WHERE {
      ?f13 wdt:P31 wd:Q11424;
           rdfs:label "Friday the 13th"@en;
           wdt:P577 ?date1.
    }
  }
  {
    SELECT (MIN(YEAR(?date2)) AS ?halloweenYear) WHERE {
      ?h wdt:P31 wd:Q11424;
         rdfs:label "Halloween"@en;
         wdt:P577 ?date2.
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (MIN(?publicationDate) AS ?firstReleaseDate) WHERE {
  wd:Q200092 wdt:P577 ?publicationDate.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?birthDate WHERE {
  VALUES ?article {
    <https://en.wikipedia.org/wiki/Jodie_Foster>
    <https://en.wikipedia.org/wiki/Julia_Roberts>
  }
  ?article schema:about ?person ;
           schema:inLanguage "en" ;
           schema:isPartOf <https://en.wikipedia.org/> .
  ?person wdt:P569 ?birthDate .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ASC(?birthDate)
LIMIT 1

SELECT ?person ?personLabel ?height WHERE {
  VALUES ?person { wd:Q13909 wd:Q35332 }
  ?person wdt:P2048 ?height.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?height)
LIMIT 1

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK WHERE {
  ?film wdt:P31 wd:Q11424;
        rdfs:label "Citizen Kane"@en;
        wdt:P577 ?date.
  FILTER (?date < "1950-01-01T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?startYear ?durationYears WHERE {
  wd:Q258 p:P35 ?st.
  ?st ps:P35 wd:Q8023;
      pq:P580 ?start;
      pq:P582 ?end.
  BIND(year(?start) AS ?startYear)
  BIND(year(?end) - year(?start) AS ?durationYears)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1

SELECT ?tom ?tomLabel ?tomDOB ?ron ?ronLabel ?ronDOB ?isTomOlder WHERE {
  ?article1 schema:about ?tom;
            schema:inLanguage "en";
            schema:isPartOf <https://en.wikipedia.org/>;
            schema:name "Tom Hanks".
  ?tom wdt:P569 ?tomDOB.
  ?article2 schema:about ?ron;
            schema:inLanguage "en";
            schema:isPartOf <https://en.wikipedia.org/>;
            schema:name "Ron Howard".
  ?ron wdt:P569 ?ronDOB.
  BIND(?tomDOB < ?ronDOB AS ?isTomOlder)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?thing ?thingLabel ?thingDate ?halloween ?halloweenLabel ?halloweenDate (?thingDate < ?halloweenDate AS ?theThingBeforeHalloween) WHERE {
  {
    SELECT ?thing (MIN(?d) AS ?thingDate) WHERE {
      ?thingArticle schema:about ?thing;
                    schema:isPartOf <https://en.wikipedia.org/>;
                    schema:name "The Thing (1982 film)"@en.
      ?thing wdt:P577 ?d.
    } GROUP BY ?thing
  }
  {
    SELECT ?halloween (MIN(?d2) AS ?halloweenDate) WHERE {
      ?halloweenArticle schema:about ?halloween;
                        schema:isPartOf <https://en.wikipedia.org/>;
                        schema:name "Halloween (1978 film)"@en.
      ?halloween wdt:P577 ?d2.
    } GROUP BY ?halloween
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel ?dob WHERE {
  VALUES ?name { "Anna Faris"@en "Jennifer Aniston"@en }
  ?item wdt:P31 wd:Q5;
        rdfs:label ?name;
        wdt:P569 ?dob.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?dob
LIMIT 1

SELECT ?person ?personLabel (MIN(?start) AS ?earliestStart) WHERE {
  VALUES ?name {"Kevin Spacey"@en "Kiefer Sutherland"@en}
  ?person rdfs:label ?name.
  ?person wdt:P31 wd:Q5.
  ?person wdt:P2031 ?start.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?person ?personLabel
ORDER BY ?earliestStart
LIMIT 1

SELECT ?film ?filmLabel ?box WHERE {
  {
    ?film wdt:P31 wd:Q11424;
          rdfs:label "Avatar"@en;
          wdt:P577 ?date;
          wdt:P2142 ?box.
    FILTER(YEAR(?date)=2009)
  }
  UNION
  {
    ?film wdt:P31 wd:Q11424;
          rdfs:label "Spectre"@en;
          wdt:P577 ?date;
          wdt:P2142 ?box.
    FILTER(YEAR(?date)=2015)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?box)
LIMIT 1

SELECT ?person ?personLabel ?height WHERE {
  VALUES ?name { "Emma Stone"@en "Winona Ryder"@en }
  ?person rdfs:label ?name;
          wdt:P31 wd:Q5;
          wdt:P106 wd:Q33999;
          wdt:P2048 ?height.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?height)
LIMIT 1

SELECT ?film ?filmLabel (MAX(?boxOffice) AS ?worldwideGross) WHERE {
  VALUES ?title { "Avengers: Age of Ultron"@en "Avengers: Endgame"@en }
  ?film wdt:P31 wd:Q11424;
        wdt:P1476 ?title;
        wdt:P2142 ?boxOffice.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?film ?filmLabel
ORDER BY DESC(?worldwideGross)
LIMIT 1

SELECT ?isElijahShorter WHERE {
  ?wood wdt:P31 wd:Q5; rdfs:label "Elijah Wood"@en; wdt:P2048 ?woodHeight.
  ?astin wdt:P31 wd:Q5; rdfs:label "Sean Astin"@en; wdt:P2048 ?astinHeight.
  BIND(?woodHeight < ?astinHeight AS ?isElijahShorter)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?film ?filmLabel ?boxOffice WHERE {
  VALUES ?title { "Toy Story"@en "Men in Black"@en }
  ?film wdt:P31 wd:Q11424;
        wdt:P1476 ?title;
        wdt:P2142 ?boxOffice.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?boxOffice)
